  filter: none;
}

/* Card resolution art is anchored to the piece/square it changes. These are
   not screen overlays: each mark lives inside the affected board cell and is
   removed as soon as that card's physical action finishes. */
.card-cell-fx { position:absolute; inset:-10%; pointer-events:none; z-index:18; overflow:visible; }
.card-cell-fx::before,.card-cell-fx::after { content:""; position:absolute; left:50%; top:50%; box-sizing:border-box; }
.card-cell-fx.fx-crown::before { width:72%; height:52%; transform:translate(-50%,-115%); background:#f3c94f; border:3px solid #251b13; clip-path:polygon(0 100%,8% 28%,30% 67%,50% 0,70% 67%,92% 28%,100% 100%); animation:fxCrownLand .72s cubic-bezier(.18,.88,.25,1) both; }
.card-cell-fx.fx-demote::before { width:68%; height:48%; background:#d24b4d; border:3px solid #251b13; clip-path:polygon(0 0,100% 0,88% 100%,12% 100%); animation:fxDemote .7s ease-in both; }
.card-cell-fx.fx-shield::before { width:78%; height:88%; border:5px solid #272018; background:linear-gradient(135deg,rgba(245,221,137,.7),rgba(66,145,169,.48)); clip-path:polygon(50% 0,92% 18%,82% 72%,50% 100%,18% 72%,8% 18%); animation:fxShieldForge .82s cubic-bezier(.2,.8,.2,1) both; }
.card-cell-fx.fx-chain::before { width:96%; height:42%; border:7px double #d6ad45; border-radius:50%; transform:translate(-50%,-50%) rotate(-24deg); filter:drop-shadow(2px 3px 0 #251b13); animation:fxChainBind .82s ease-out both; }
.card-cell-fx.fx-trap::before { width:88%; height:52%; border:7px dashed #d29a3d; border-radius:50%; transform:translate(-50%,-50%) scaleY(.56); filter:drop-shadow(2px 3px 0 #251b13); animation:fxTrapSnap .7s cubic-bezier(.15,.9,.25,1) both; }
.card-cell-fx.fx-ambush::before { width:12%; height:95%; background:#f1d078; border:3px solid #251b13; transform-origin:50% 90%; animation:fxDagger .7s ease-in-out both; }
.card-cell-fx.fx-portal::before { width:88%; height:88%; border:7px double #8b63ba; border-radius:50%; box-shadow:inset 0 0 0 7px rgba(245,211,86,.55); animation:fxPortal .82s ease-in-out both; }
.card-cell-fx.fx-step::before { width:92%; height:18%; background:#f4d56e; border:3px solid #251b13; clip-path:polygon(0 28%,68% 28%,68% 0,100% 50%,68% 100%,68% 72%,0 72%); animation:fxStep .62s ease-out both; }
.card-cell-fx.fx-banner::before { width:12%; height:105%; background:#e3b849; border:2px solid #251b13; transform:translate(-50%,-50%); animation:fxBannerRise .88s ease-out both; }
.card-cell-fx.fx-banner::after { width:65%; height:45%; background:#bd3d4b; border:3px solid #251b13; clip-path:polygon(0 0,100% 10%,72% 52%,100% 92%,0 100%); animation:fxBannerCloth .88s ease-out both; }
.card-cell-fx.fx-strings::before { width:84%; height:100%; border-left:3px solid #e0bd56; border-right:3px solid #e0bd56; transform:translate(-50%,-72%); animation:fxStrings .82s ease-in-out both; }
.card-cell-fx.fx-fire::before { width:76%; height:92%; background:linear-gradient(#ffd856,#e94f31 70%); border:3px solid #251b13; clip-path:polygon(50% 0,68% 36%,88% 18%,82% 72%,50% 100%,15% 78%,8% 38%,34% 52%); animation:fxFlame .82s ease-out both; }
.card-cell-fx.fx-cards::before { width:58%; height:82%; background:#f4e7bb; border:4px solid #251b13; box-shadow:-9px 7px 0 #467e9c,9px -6px 0 #c6464e; animation:fxCardsDeal .82s cubic-bezier(.2,.85,.2,1) both; }
.card-cell-fx.fx-sun::before { width:72%; height:72%; border-radius:50%; background:#fff0a1; border:4px solid #251b13; box-shadow:0 0 0 8px #dda83a; animation:fxSun .9s ease-out both; }
@keyframes fxCrownLand { 0%{transform:translate(-50%,-210%) rotate(-12deg);opacity:0}65%{transform:translate(-50%,-92%) rotate(5deg);opacity:1}100%{transform:translate(-50%,-115%);opacity:0} }
@keyframes fxDemote { 0%{transform:translate(-50%,-120%) scale(1.15);opacity:0}55%{opacity:1}100%{transform:translate(-50%,65%) scale(.55) rotate(12deg);opacity:0} }
@keyframes fxShieldForge { 0%{transform:translate(-50%,-50%) scale(.08) rotate(-25deg);opacity:0}55%{transform:translate(-50%,-50%) scale(1.12) rotate(3deg);opacity:1}100%{transform:translate(-50%,-50%) scale(1);opacity:0} }
@keyframes fxChainBind { 0%{transform:translate(-50%,-50%) rotate(-70deg) scale(1.8);opacity:0}55%{opacity:1}100%{transform:translate(-50%,-50%) rotate(-24deg) scale(.75);opacity:0} }
@keyframes fxTrapSnap { 0%{transform:translate(-50%,-50%) scaleY(.1) scaleX(1.35);opacity:0}45%{opacity:1}70%{transform:translate(-50%,-50%) scaleY(.85) scaleX(.85)}100%{transform:translate(-50%,-50%) scaleY(.5);opacity:0} }
@keyframes fxDagger { 0%{transform:translate(-50%,-190%) rotate(-35deg);opacity:0}55%{opacity:1}100%{transform:translate(-50%,30%) rotate(12deg);opacity:0} }
@keyframes fxPortal { 0%{transform:translate(-50%,-50%) scale(.12) rotate(-80deg);opacity:0}50%{opacity:1}100%{transform:translate(-50%,-50%) scale(1.18) rotate(100deg);opacity:0} }
@keyframes fxStep { 0%{transform:translate(-125%,-50%) scaleX(.3);opacity:0}45%{opacity:1}100%{transform:translate(5%,-50%) scaleX(1);opacity:0} }
@keyframes fxBannerRise { 0%{transform:translate(-50%,55%);opacity:0}55%{opacity:1}100%{transform:translate(-50%,-50%);opacity:0} }
@keyframes fxBannerCloth { 0%{transform:translate(-45%,55%) scaleX(.15);opacity:0}60%{transform:translate(-5%,-70%) scaleX(1.08);opacity:1}100%{transform:translate(-5%,-70%);opacity:0} }
@keyframes fxStrings { 0%{transform:translate(-50%,-150%);opacity:0}55%{opacity:1}100%{transform:translate(-50%,-42%);opacity:0} }
@keyframes fxFlame { 0%{transform:translate(-50%,20%) scale(.2);opacity:0}55%{transform:translate(-50%,-55%) scale(1.15);opacity:1}100%{transform:translate(-50%,-75%) scale(.65);opacity:0} }
@keyframes fxCardsDeal { 0%{transform:translate(-50%,-50%) scale(.15) rotate(-30deg);opacity:0}55%{transform:translate(-50%,-50%) scale(1.1) rotate(5deg);opacity:1}100%{transform:translate(-50%,-90%) scale(.75);opacity:0} }
@keyframes fxSun { 0%{transform:translate(-50%,-50%) scale(.1) rotate(-45deg);opacity:0}55%{transform:translate(-50%,-50%) scale(1.25) rotate(15deg);opacity:1}100%{transform:translate(-50%,-50%) scale(1.6) rotate(40deg);opacity:0} }

/* At crowded levels, dozens of independent infinite CSS animations create
   more compositor work than the actual game. Preserve every hazard/status
   visually, but hold the tiny ambient loops still while the board is dense;
   major card animations continue at full strength on their canvas. */
.dense-board .wildfire-flame,
.dense-board .poison-bubble,
.dense-board .piece.shielded::after,
.dense-board .piece.countering::after,
.dense-board .piece.ambushed::after {
  animation-play-state: paused !important;
}

/* The generic full-screen impact burst has been retired. Card-specific board
   animations remain intact, but no additional overlay may cover them. */
.cartoon-card-flourish,
.cartoon-card-flourish::before,
.cartoon-flourish-banner,
.cartoon-flourish-spark {
  display: none !important;
  animation: none !important;
}

@media (max-width: 560px) {
  .app { padding: .35rem; gap: .36rem; }
  header { border-width: 3px; }
  .board-tilt { padding: 8px !important; border-width: 3px; }
  .status-bar { border-width: 3px; padding: .4rem .45rem; }
  .message { border-width: 2px; }
  .cards-hand { min-height: 119px; padding: 6px 4px 5px; gap: 2px; }
  .stack-wrap { flex-basis: 62px; }
  .rarity-stack { width: 58px; height: 87px; }
  .status-bar { gap: .16rem; }
  .status-item.glory-status { min-width: 3.35rem; padding-left: .2rem; }
  .glory-status .status-label { font-size: .38rem; }
  .glory-status .status-value { font-size: .88rem; }
  .glory-multiplier { font-size: .34rem; letter-spacing: 0; }
}
  /* Manuscript-edition effects: preserve the original gameplay timing while
     pushing every dedicated canvas animation into the brighter flat palette. */
  .manuscript-fx-canvas {
    /* Keep the canvas itself unfiltered. A full-board CSS filter forces an
       expensive offscreen texture on every animation frame; the richer color
       and ink work now lives inside each canvas drawing instead. */
    filter: saturate(1.32) contrast(1.1) drop-shadow(1px 2px 0 rgba(31,24,17,.42));
    image-rendering: auto;
  }
  .manuscript-fx-accent {
    display: none !important;
  }
  .lazarus-board-light, .divine-intervention-light, .sands-time-wash {
    border: 5px solid #211a13 !important;
    box-shadow: inset 0 0 0 3px #ffe58b, inset 0 0 52px rgba(255,205,67,.55), 0 7px 0 rgba(0,0,0,.6) !important;
    filter: saturate(1.25) contrast(1.05);
  }
  .charge-impact-flash {
    background: radial-gradient(circle, #fff7d6 0 10%, #e1ad35 11% 28%, #2476b8 29% 42%, transparent 44%) !important;
    border: 3px solid #2d2923;
    box-shadow: 0 0 0 3px #f1dfb4, 0 0 22px #e1ad35;
  }
  .piece-art { filter: saturate(.86) contrast(.92) brightness(.97); }

  /* Card Collection rarity language: preserve the artwork while making the
     surrounding tier color unmistakable at a glance. */
  .collection-card-wrap {
    position: relative;
    padding: 7px;
    border: 3px solid transparent;
    border-radius: 14px;
  }
  .collection-card-wrap::before {
    content: attr(data-rarity-label);
    display: block;
    margin: -2px 0 6px;
    font-family: var(--font-card-name);
    font-size: .66rem;
    font-weight: 900;
    letter-spacing: .13em;
    text-align: center;
    text-transform: uppercase;
  }
  .collection-card-wrap.collection-rarity-common {
    background: linear-gradient(155deg, #272522, #090909);
    border-color: #6f6a61;
  }
  .collection-card-wrap.collection-rarity-common::before { color: #eee5d4; }
  .collection-card-wrap.collection-rarity-common .card {
    border-color: #6e6659 !important;
  }
  .collection-card-wrap.collection-rarity-uncommon {
    background: linear-gradient(155deg, #294c38, #0d2016);
    border-color: #78ad7d;
  }
  .collection-card-wrap.collection-rarity-uncommon::before { color: #bde7bf; }
  .collection-card-wrap.collection-rarity-uncommon .card {
    border-color: #617d69 !important;
  }
  .collection-card-wrap.collection-rarity-rare {
    background: linear-gradient(155deg, #294f77, #0b1b30);
    border-color: #76a9dc;
  }
  .collection-card-wrap.collection-rarity-rare::before { color: #cbe5ff; }
  .collection-card-wrap.collection-rarity-rare .card {
    border-color: #607c90 !important;
  }
  .collection-card-wrap.collection-rarity-epic {
    background: linear-gradient(155deg, #856416, #2b1b05);
    border-color: #f2cf62;
  }
  .collection-card-wrap.collection-rarity-epic::before { color: #fff0a8; }
  .collection-card-wrap.collection-rarity-epic .card {
    border-color: #897548 !important;
  }
  .collection-card-wrap.collection-rarity-white {
    background: linear-gradient(155deg, #e7e2d7, #77746e);
    border-color: #fff;
  }
  .collection-card-wrap.collection-rarity-white::before { color: #171717; }
  .collection-card-wrap.collection-rarity-white .card {
    border-color: #8a867e !important;
  }
  .collection-card-wrap.collection-locked::after { top: 46%; }

  /* High-contrast upgrade panel; the manuscript override had made this
     cream-on-cream and difficult to read. */
  .mastery-orb-popup {
    background: linear-gradient(160deg, #17241e, #080d0b) !important;
    border: 4px solid #d6a934 !important;
    box-shadow: 0 10px 0 rgba(0,0,0,.8), inset 0 0 0 2px #435f50 !important;
    color: #f7edd5 !important;
  }
  .mastery-orb-popup-title { color: #f0ca62 !important; text-shadow: 2px 2px 0 #000; }
  .mastery-orb-popup-base,
  .mastery-orb-popup-tiers {
    background: #101713 !important;
    border: 2px solid #6b8c76 !important;
    color: #f7edd5 !important;
  }
  .mastery-orb-popup-base strong,
  .mastery-orb-popup-tiers .tier-reached { color: #ffd66e !important; }
  .mastery-orb-popup-shards,
  .mastery-orb-popup-close { color: #e4d8bd !important; }
  .mastery-orb-popup-btn {
    background: linear-gradient(160deg, #44664f, #17271d) !important;
    color: #fff1bd !important;
    border-color: #e6bd52 !important;
  }

  /* Collection cards keep the full artwork, but their copy must remain
     inside the physical card at every grid width. */
  .collection-grid .card .card-inner {
    height: 100%;
    min-height: 0;
    overflow: hidden;
    padding: .22rem .18rem;
    gap: .08rem;
  }
  .collection-grid .card .card-name {
    font-size: .58rem;
    line-height: 1.08;
  }
  .collection-grid .card .card-desc {
    font-size: .56rem;
    line-height: 1.16;
    padding: 0 .08rem;
    overflow: hidden;
  }

  .mastery-orb-back-btn {
    position: fixed;
    top: max(14px, env(safe-area-inset-top));
    left: max(14px, env(safe-area-inset-left));
    z-index: 5310;
    min-width: 88px;
    padding: .55rem .8rem;
    border: 3px solid #211a13;
    border-radius: 10px;
    background: #f1dfb4;
    color: #211a13;
    box-shadow: 0 4px 0 #211a13;
    font-family: var(--font-body);
    font-weight: 900;
    font-size: .82rem;
    letter-spacing: .05em;
    cursor: pointer;
  }
  .mastery-orb-back-btn:active {
    transform: translateY(3px);
    box-shadow: 0 1px 0 #211a13;
  }

  /* Make rarity readable as a frame, not a hairline. The enlarged card's
     inline border-color still supplies the correct rarity color. */
  .collection-card-wrap {
    border-width: 6px;
    border-color: #756f64 !important;
    box-shadow: 0 7px 0 rgba(0,0,0,.72), inset 0 0 0 2px rgba(255,255,255,.12);
  }
  /* No decorative inset frame: the physical card edge is the only border. */
  .collection-grid .card::before {
    display: none !important;
  }
  .collection-grid .card {
    border-width: 5px !important;
    border-style: solid !important;
  }
  /* Remove the older inset box-shadow that only remained visible around the
     artwork. The ::before rule above is now the one and only inner frame. */
  .collection-grid .collection-card-wrap .card {
    box-shadow: 5px 7px 0 rgba(0,0,0,.72) !important;
  }
  .card-enlarge-stage {
    border-width: 8px !important;
    box-shadow: 0 11px 0 rgba(0,0,0,.82), 0 0 0 3px rgba(255,255,255,.12), inset 0 0 0 3px #17130f !important;
  }

  /* The card face keeps its artwork untouched while the lower copy panel
     gains just enough depth for the white title and gold description. */
  .card .card-inner {
    background: linear-gradient(to bottom, transparent 0 48%, #5a4c37 48% 100%);
  }
  .card.uncommon .card-inner {
    background: linear-gradient(to bottom, transparent 0 48%, #466952 48% 100%);
  }
  .card.rare .card-inner {
    background: linear-gradient(to bottom, transparent 0 48%, #46677d 48% 100%);
  }
  .card.epic-card .card-inner {
    background: linear-gradient(to bottom, transparent 0 48%, #725d30 48% 100%);
  }
  .card.white-card .card-inner {
    background: linear-gradient(to bottom, transparent 0 48%, #746f65 48% 100%);
  }
  /* Use the real card edge in every view—never draw a second inset frame. */
  .card::before,
  .reward-choice-card::before {
    display: none !important;
    content: none !important;
  }
  /* Every manuscript illustration is a true square. Keep the complete image
     instead of forcing it into a short landscape window and zoom-cropping its
     main subject. The card grows around the art; the source bitmap is never
     clipped, stretched, or distorted. */
  .card .card-art {
    width: calc(100% + .5rem);
    margin: -.3rem -.25rem 0;
    border-radius: 0;
    height: auto !important;
    min-height: 0 !important;
    aspect-ratio: 1 / 1;
    flex: 0 0 auto;
  }
  .card .card-art img,
  .big-card-art img,
  .preview-art img {
    width: 100% !important;
    height: 100% !important;
    top: 0 !important;
    right: auto !important;
    bottom: auto !important;
    left: 0 !important;
    object-fit: contain !important;
    opacity: 1 !important;
    filter: saturate(1.07) contrast(1.02) !important;
    transform: none !important;
  }
  .big-card-art,
  .preview-art,
  .carousel-overlay-stage .card.carousel-full-card .big-card-art,
  .carousel-overlay-stage .card.carousel-full-card.card-detail-mode .big-card-art,
  .carousel-overlay-stage .card.card-detail-mode .preview-art {
    width: 100%;
    height: auto !important;
    min-height: 0 !important;
    aspect-ratio: 1 / 1;
    flex: 0 0 auto !important;
  }
  /* The old divider read as a blank strip below the illustration. The image
     now meets the copy panel directly in every card view. */
  .card-art-divider,
  .big-card-divider,
  .preview-divider {
    display: none !important;
  }
  /* Every card at a given size uses the same typography. Long titles wrap
     cleanly instead of being individually shrunk by JavaScript. */
  .card-name {
    white-space: normal !important;
    overflow: hidden;
    text-overflow: clip;
    overflow-wrap: normal;
    word-break: normal;
    min-height: 1.08em;
    max-height: 2.16em;
  }
  .collection-grid .card .card-desc,
  .starter-deck-grid .card .card-desc {
    flex: 1 1 auto;
    min-height: 0;
  }
  .collection-grid .card .mastery-orbs,
  .starter-deck-grid .card .mastery-orbs {
    margin-top: auto;
    flex-shrink: 0;
  }
  /* Center the description inside the space between the title and upgrade
     orbs. This gives the copy equal breathing room above and below without
     changing its font size or making the physical card any taller. */
  .collection-grid .card .card-desc,
  .starter-deck-grid .card .card-desc {
    display: flex;
    align-items: center;
    justify-content: center;
  }
  /* Enlarged and carousel cards use gap for both separations. Remove the old
     one-sided orb offset so title-to-description and description-to-orbs are
     visually balanced there as well. */
  .big-card-body > .mastery-orbs,
  .carousel-overlay-stage .card.card-detail-mode .mastery-orbs {
    margin-top: 0;
    padding-top: 0;
  }
  /* Keep the upgrade row clear of the physical card edge in every card
     presentation. Longer three-line descriptions can consume all remaining
     flex space; lifting the row itself prevents its circles from being
     clipped by the card's bottom border without changing card dimensions or
     shrinking the shared typography. */
  .card .mastery-orbs {
    position: relative;
    bottom: 4px;
    margin-bottom: 2px;
  }
  .big-card-body > .mastery-orbs,
  .carousel-overlay-stage .card.card-detail-mode .mastery-orbs {
    bottom: 2px;
    margin-bottom: 2px;
  }
  .big-card-body {
    background: linear-gradient(160deg, #68583f, #493d2c);
  }
  .card.uncommon .big-card-body,
  .card-enlarge-stage[data-rarity="uncommon"] .big-card-body {
    background: linear-gradient(160deg, #557b61, #395542);
  }
  .card.rare .big-card-body,
  .card-enlarge-stage[data-rarity="rare"] .big-card-body {
    background: linear-gradient(160deg, #55788e, #385568);
  }
  .card.epic-card .big-card-body,
  .card-enlarge-stage[data-rarity="epic"] .big-card-body {
    background: linear-gradient(160deg, #846d39, #594820);
  }
  .card.white-card .big-card-body,
  .card-enlarge-stage[data-rarity="white"] .big-card-body {
    background: linear-gradient(160deg, #858076, #625e56);
  }

  /* This is the base/orb summary shown above an enlarged Collection card.
     It must be legible before the player taps an individual upgrade orb. */
  .collection-rules-float {
    background: linear-gradient(160deg, #17241e, #080d0b) !important;
    color: #f7edd5 !important;
    border: 4px solid #d6a934 !important;
    box-shadow: 0 7px 0 rgba(0,0,0,.82), inset 0 0 0 2px #435f50 !important;
  }
  .collection-rules-float .card-rules-summary {
    background: #101713 !important;
    border-color: #6b8c76 !important;
  }
  .collection-rules-float .card-rule-row,
  .collection-rules-float .card-rule-text {
    color: #f7edd5 !important;
  }
  .collection-rules-float .card-rule-label {
    color: #ffd66e !important;
  }

  /* Glory Edition card packs. The wrapper tears into two physical halves;
     the revealed card uses the same renderer as every other card view. */
  #winOverlay {
    justify-content: center;
    gap: clamp(.55rem, 1.5vh, 1rem);
    padding: clamp(1.15rem, 3vh, 2rem) clamp(1rem, 4vw, 3rem);
    background:
      linear-gradient(rgba(26,12,5,.26), rgba(18,8,4,.42)),
      #4b2817 url('data:image/png;base64,') center / cover no-repeat;
  }
  #winOverlay::after { display: none; }
  #winOverlay > * { position: relative; z-index: 1; }
  #winOverlay .overlay-title {
    width: min(1120px, 88vw);
    max-width: 88vw;
    font-size: clamp(2.15rem, 5vw, 4.25rem);
    line-height: .96;
    letter-spacing: .055em;
    white-space: normal;
    overflow-wrap: anywhere;
    flex: 0 0 auto;
  }
  #winOverlay .overlay-sub {
    max-width: min(720px, 86vw);
    padding: .28rem .72rem;
    border-radius: 7px;
    background: rgba(20,9,4,.56);
    text-shadow: 1px 2px 0 #160b06;
    flex: 0 0 auto;
  }
  #winOverlay #continueBtn {
    flex: 0 0 auto;
    margin: .15rem 0 max(.35rem, 1vh);
  }
  .card-pack-stage {
    width: min(820px, 92vw);
    min-height: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: clamp(.7rem, 2.6vw, 1.4rem);
    flex-wrap: wrap;
    padding: clamp(.45rem, 1.4vw, .8rem);
    perspective: 1100px;
    background: transparent;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    flex: 0 1 auto;
  }
  .glory-pack {
    position: relative;
    width: clamp(138px, 24vw, 188px);
    height: clamp(207px, 36vw, 282px);
    flex: 0 0 clamp(138px, 24vw, 188px);
    border: 0;
    padding: 0;
    background: transparent;
    color: #fff5d8;
    cursor: pointer;
    filter: drop-shadow(0 12px 10px rgba(0,0,0,.55));
    transform-style: preserve-3d;
    -webkit-tap-highlight-color: transparent;
  }
  .glory-pack:hover:not(.locked):not(.opened) { transform: translateY(-7px) rotate(-1deg); }
  .glory-pack.locked { filter: grayscale(.8) brightness(.58) drop-shadow(0 8px 7px rgba(0,0,0,.45)); cursor: not-allowed; }
  .glory-pack[data-rarity="epic"]:not(.locked) {
    filter: drop-shadow(0 0 12px rgba(255,205,74,.5)) drop-shadow(0 12px 10px rgba(0,0,0,.58));
  }
  .glory-pack-half {
    position: absolute;
    left: 0;
    width: 100%;
    height: 52%;
    overflow: hidden;
    backface-visibility: hidden;
  }
  .glory-pack-art {
    position: absolute;
    left: 0;
    width: 100%;
    height: 192%;
    object-fit: fill;
    pointer-events: none;
    user-select: none;
  }
  .glory-pack-top { top: 0; transform-origin: 15% 100%; }
  .glory-pack-top .glory-pack-art { top: 0; }
  .glory-pack-bottom { bottom: 0; transform-origin: 85% 0; }
  .glory-pack-bottom .glory-pack-art { bottom: 0; }
  .glory-pack-copy {
    position: absolute;
    left: 7%;
    right: 7%;
    bottom: 5%;
    z-index: 3;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-end;
    pointer-events: none;
    text-align: center;
    text-transform: uppercase;
    text-shadow: 2px 2px 0 rgba(0,0,0,.75);
  }
  .glory-pack-crest { display: none; }
  .glory-pack-price { font-family: var(--font-mono); font-weight: 800; font-size: clamp(.72rem, 2.1vw, .95rem); color: #ffe08a; }
  .glory-pack-price {
    padding: .18rem .42rem;
    border-radius: 5px;
    background: rgba(12,10,8,.72);
    box-shadow: 0 2px 0 rgba(0,0,0,.45);
  }
  .glory-pack.opening { pointer-events: none; animation: gloryPackShake .5s ease-in-out both; }
  .glory-pack.opening .glory-pack-copy { animation: gloryPackCopyVanish .22s .24s forwards; }
  .glory-pack.opening .glory-pack-top { animation: gloryPackTopTear .8s .24s cubic-bezier(.2,.78,.2,1) forwards; }
  .glory-pack.opening .glory-pack-bottom { animation: gloryPackBottomTear .8s .24s cubic-bezier(.2,.78,.2,1) forwards; }
  .glory-pack-stage.pack-revealing .glory-pack:not(.opening) { opacity: .18; transform: scale(.88); pointer-events: none; }
  .card-pack-reveal.card-enlarge-stage {
    width: min(72vw, 340px);
    /* The reveal combines a complete square illustration with a variable
       title/description/orb panel. A fixed aspect ratio made longer cards
       overflow that box and hid their bottom edge. Let the actual contents
       establish the height; #winOverlay already scrolls on short screens. */
    height: auto;
    max-height: none;
    aspect-ratio: auto;
    animation: gloryPackCardReveal .7s cubic-bezier(.15,1.22,.35,1) both;
    filter: drop-shadow(0 0 24px rgba(255,218,92,.52));
    flex: 0 0 auto;
  }
  .card-pack-reveal .big-card-body {
    flex: 0 0 auto;
    min-height: 0;
    overflow: visible;
    padding-bottom: calc(1rem + 4px);
  }
  @keyframes gloryPackShake {
    0%,100% { transform: rotate(0) scale(1); }
    20% { transform: rotate(-4deg) scale(1.035); }
    40% { transform: rotate(4deg) scale(1.055); }
    60% { transform: rotate(-3deg) scale(1.06); }
    80% { transform: rotate(2deg) scale(1.04); }
  }
  @keyframes gloryPackCopyVanish { to { opacity: 0; transform: scale(1.2); } }
  @keyframes gloryPackTopTear { to { transform: translate(-48%,-78%) rotate(-24deg); opacity: 0; } }
  @keyframes gloryPackBottomTear { to { transform: translate(48%,78%) rotate(20deg); opacity: 0; } }
  @keyframes gloryPackCardReveal {
    0% { opacity: 0; transform: translateY(50px) rotateY(90deg) scale(.58); }
    58% { opacity: 1; transform: translateY(-10px) rotateY(-8deg) scale(1.08); }
    100% { opacity: 1; transform: translateY(0) rotateY(0) scale(1); }
  }
  @media (max-width: 520px) {
    #winOverlay {
      justify-content: center;
      gap: .45rem;
      min-height: 100dvh;
      padding: max(1rem, env(safe-area-inset-top)) .55rem max(1.25rem, env(safe-area-inset-bottom));
    }
    #winOverlay .overlay-title { width: 94vw; max-width: 94vw; font-size: clamp(1.75rem, 9vw, 2.65rem); }
    #winOverlay .overlay-sub { font-size: .68rem; line-height: 1.35; }
    .card-pack-stage { gap: .45rem; padding: .35rem .1rem; }
    .glory-pack { width: min(28vw, 144px); height: min(42vw, 216px); flex-basis: min(28vw, 144px); }
    .glory-pack-copy { inset-inline: 3%; }
    .card-pack-reveal.card-enlarge-stage { width: min(68vw, 300px); max-height: none; }
    #winOverlay #continueBtn { margin-bottom: 1rem; }
  }
  @media (max-height: 720px) and (min-width: 521px) {
    #winOverlay { gap: .35rem; padding-block: .65rem; }
    #winOverlay .overlay-title { font-size: clamp(1.75rem, 5vw, 3rem); }
    #winOverlay .overlay-sub { line-height: 1.25; padding-block: .18rem; }
    .card-pack-reveal.card-enlarge-stage { width: min(29vw, 270px); max-height: none; }
  }